MODEL="""export function addTask(rows,title){const clean=title.trim();if(!clean)throw new Error('Titolo vuoto');return [...rows,{id:Math.max(0,...rows.map(r=>r.id))+1,title:clean,done:false}];}
export function completed(rows){return rows.filter(row=>row.done).length;}
"""
MODEL_TEST="""import test from 'node:test';import assert from 'node:assert/strict';import {addTask,completed} from '../src/model.mjs';
test('rifiuta un titolo vuoto',()=>assert.throws(()=>addTask([],'  ')));
test('assegna ID e non muta origine',()=>{const old=[{id:4,title:'prima',done:true}];const next=addTask(old,' seconda ');assert.equal(next[1].id,5);assert.equal(next[1].title,'seconda');assert.equal(old.length,1);});
test('conta soltanto completate',()=>assert.equal(completed([{done:true},{done:false}]),1));
"""

def lifecycle(book,stack,wrapper):
    if stack=="vue":base=("const count=ref(0);",'<button @click="count++">Clic: {{count}}</button>')
    elif stack=="svelte":base=("let count=$state(0);",'<button onclick={()=>count++}>Clic: {count}</button>')
    else:base=("count=signal(0);increment(){this.count.update(n=>n+1);}",'<button (click)="increment()">Clic: {{count()}}</button>')
    start=wrapper(*base)
    book.add("setup","Inizializzare ambiente e prima applicazione "+stack,"Installare dipendenze compatibili con la versione di Node e avviare un componente completo sul loopback.",start,section="Inizializzazione",commands="node --version\nnpm install\nnpm run dev",explanation=f"## Ambiente\n{book.prerequisites}\n\n## File\nEsporta tutti i file nella stessa cartella. Il manifest fissa le versioni dirette; npm install genera il lockfile da conservare. I file del componente sono in src.\n\n## Avvio\nApri il terminale nella cartella del manifest, controlla Node, installa e avvia il server. Segui l'URL 127.0.0.1 stampato dal tool. Il pulsante incrementa un valore di sessione. Interrompi il server con Ctrl+C. Non viene creato un servizio pubblico.",expected="Il pulsante mostra il numero di clic senza ricaricare la pagina.",tags=[stack,"setup","install","Node","localhost"])
    build=deepcopy(start)
    book.add("build","Compilare e ispezionare l'output di produzione "+stack,"Generare un output ottimizzato a partire dagli stessi file sorgente ed evitare di distribuire il server di sviluppo.",build,section="Compilazione",commands="npm install\nnpm run build",explanation=f"## Build\nInstalla dal manifest esportato e lancia npm run build. {'Angular usa @angular/build:application e scrive dist/atlas/browser.' if stack=='angular' else 'Vite usa il plugin del framework e scrive dist, con asset nominati per hash.'}\n\n## Controllo\nControlla index.html e i riferimenti ai file JS/CSS. Errori del compilatore non vanno ignorati: un build precedente nella cartella dist non prova che l'ultimo sorgente sia valido. L'app è soltanto client-side, senza endpoint o segreti server.",expected="Il comando produce la directory dist senza errori di compilazione.",tags=[stack,"build","production","dist"])
    debug=deepcopy(start)
    port=4200 if stack=="angular" else 5173
    debug[".vscode/launch.json"]=js({"version":"0.2.0","configurations":[{"name":"Debug browser locale","type":"msedge","request":"launch","url":f"http://127.0.0.1:{port}","webRoot":"${workspaceFolder}/src"}]})
    book.add("debug","Seguire un evento del componente nel debugger "+stack,"Usare source map e breakpoint sulla modifica di stato nel browser locale.",debug,section="Debug",commands="npm install\nnpm run dev",explanation=f"## Sessione\nApri la cartella in VS Code e avvia il server locale sul porto {port}. Se il tool sceglie un'altra porta, modifica url in launch.json. Avvia Debug browser locale con Edge disponibile.\n\n## Breakpoint\nApri {'src/app.ts' if stack=='angular' else 'src/App.'+('vue' if stack=='vue' else 'svelte')}, metti il breakpoint nell'handler del clic o usa gli strumenti del browser per fermarti sugli eventi click. Premi il pulsante e osserva lo stato. Il debugger non avvia da solo il server; interrompi entrambi al termine.",expected="Il debugger vede il sorgente originale e la variazione del contatore.",tags=[stack,"debug","source maps","VS Code","breakpoint"])
    testfiles=deepcopy(start);testfiles.update({"src/model.mjs":MODEL,"test/model.test.mjs":MODEL_TEST})
    book.add("test","Testare logica pura separata dal componente "+stack,"Verificare validazione, ID e immutabilità con il test runner Node senza confondere il test del modello con una prova UI.",testfiles,section="Test",commands="node --test\nnpm install\nnpm run build",explanation="## Confine del test\nsrc/model.mjs contiene operazioni pure di una lista attività. test/model.test.mjs controlla input vuoto, ID crescente, origine immutata e conteggio. node --test non richiede un DOM e non sostituisce una prova degli eventi del componente.\n\n## Esecuzione\nEsegui i test dalla radice; poi installa e compila per controllare anche gli import del framework. Un test fallito deve interrompere la consegna del modello.",expected="Tre test del modello passano; la build è una verifica separata del componente.",tags=[stack,"test","node:test","validation","immutable"])
    deploy=deepcopy(start)
    if stack=="angular":commands='npm install\nnpm run build -- --base-href /laboratorio/'
    else:
        config=deploy['vite.config.js'];deploy['vite.config.js']=config.replace("defineConfig({","defineConfig({base:'/laboratorio/',")
        commands="npm install\nnpm run build\nnpm run preview"
    book.add("deploy","Preparare il frontend per una sottocartella "+stack,"Impostare il percorso base degli asset quando l'app viene ospitata sotto /laboratorio/.",deploy,section="Distribuzione",commands=commands,explanation=f"## Percorso base\nLa configurazione usa /laboratorio/ come prefisso. {'Il parametro --base-href viene passato al builder Angular.' if stack=='angular' else 'base in vite.config.js riscrive i riferimenti agli asset prodotti.'}\n\n## Consegna\nDistribuisci il contenuto di {'dist/atlas/browser' if stack=='angular' else 'dist'} a un server statico che lo esponga sotto quel prefisso. Il ricettario non pubblica nulla. In caso di percorsi client-side occorre configurare il fallback HTML sul server; questo esempio non implementa routing. Verifica i file nell'output e le risposte HTTP, non soltanto la pagina iniziale.",expected="I riferimenti degli asset compilati includono /laboratorio/.",tags=[stack,"deploy","base path","static hosting"])

def capstone(book,stack):
    extra={"src/model.mjs":MODEL,"test/model.test.mjs":MODEL_TEST,"README.md":"# Attività locali\nInstallare dipendenze, eseguire node --test e npm run build. Il modello valida titoli e ID. La UI usa stato del framework; i test non simulano un browser. Nessun servizio remoto.\n"}
    if stack=="vue":
        code="import {addTask,completed} from './model.mjs';const rows=ref([]);const title=ref('');const error=ref('');const done=computed(()=>completed(rows.value));function add(){try{rows.value=addTask(rows.value,title.value);title.value='';error.value='';}catch(e){error.value=e.message;}}function toggle(id){rows.value=rows.value.map(row=>row.id===id?{...row,done:!row.done}:row);}"
        template='<h1>Attività</h1><form @submit.prevent="add"><input v-model="title" aria-label="Nuova attività"><button>Aggiungi</button></form><p class="error" role="status">{{error}}</p><ul><li v-for="row in rows" :key="row.id"><label><input type="checkbox" :checked="row.done" @change="toggle(row.id)">{{row.title}}</label></li></ul><p>Completate: {{done}}</p>'
        files=vue_files(code,template,extra)
    elif stack=="svelte":
        code="import {addTask,completed} from './model.mjs';let rows=$state([]);let title=$state('');let error=$state('');let done=$derived(completed(rows));function add(event){event.preventDefault();try{rows=addTask(rows,title);title='';error='';}catch(e){error=e.message;}}function toggle(id){rows=rows.map(row=>row.id===id?{...row,done:!row.done}:row);}"
        template='<h1>Attività</h1><form onsubmit={add}><input bind:value={title} aria-label="Nuova attività"><button>Aggiungi</button></form><p class="error" role="status">{error}</p><ul>{#each rows as row (row.id)}<li><label><input type="checkbox" checked={row.done} onchange={()=>toggle(row.id)}>{row.title}</label></li>{/each}</ul><p>Completate: {done}</p>'
        files=svelte_files(code,template,extra)
    else:
        # Angular strict compilation uses a typed model; the testable ESM model
        # supplies the same domain algorithm for command-line regression checks.
        extra['src/model.d.mts']="export interface Task{id:number;title:string;done:boolean}export function addTask(rows:Task[],title:string):Task[];export function completed(rows:Task[]):number;"
        code="rows=signal<Task[]>([]);title='';error=signal('');done=computed(()=>completed(this.rows()));add(){try{this.rows.set(addTask(this.rows(),this.title));this.title='';this.error.set('');}catch(e){this.error.set(e instanceof Error?e.message:String(e));}}toggle(id:number){this.rows.update(rows=>rows.map(row=>row.id===id?{...row,done:!row.done}:row));}"
        template='<h1>Attività</h1><form (ngSubmit)="add()"><input name="title" [(ngModel)]="title" aria-label="Nuova attività"><button>Aggiungi</button></form><p class="error" role="status">{{error()}}</p><ul>@for(row of rows();track row.id){<li><label><input type="checkbox" [checked]="row.done" (change)="toggle(row.id)">{{row.title}}</label></li>}</ul><p>Completate: {{done()}}</p>'
        files=angular_files(code,template,extra,"import {Task,addTask,completed} from './model.mjs';")
    book.add("progetto-attivita","Progetto completo: attività con stato e validazione "+stack,"Aggiungere attività con ID stabili, alternare il completamento e tenere separati modello e interfaccia.",files,section="Inizializzazione",project=True,commands="npm install\nnode --test\nnpm run build\nnpm run dev",explanation="## Progetto\nEsporta l'intera struttura. Il modello rifiuta titoli vuoti, assegna il prossimo ID e restituisce una nuova lista. La UI mantiene lo stato con gli strumenti del framework e visualizza gli errori nel modulo. I dati sono soltanto di sessione, quindi ricaricare azzera la lista.\n\n## Controlli\nInvia un titolo vuoto: compare un errore. Aggiungi due attività, spunta la seconda e verifica il conteggio1; togli la spunta e verifica0. Esegui node --test per i casi del modello e npm run build per il progetto completo. Un build riuscito non attesta una sessione browser interattiva.",expected="Tre test del modello passano; aggiunta e completamento aggiornano il conteggio visibile.",tags=[stack,"project","state","forms","test","immutable"])

def build_all():
    assert len(VUE)==29,len(VUE)
    assert len(SVELTE)==24,len(SVELTE)
    assert len(ANGULAR)==24,len(ANGULAR)
    for stack,rows,wrapper,version,sources in [("vue",VUE,vue_files,"Vue3.5.44;Vite8.3.5;plugin-vue6.0.10",["https://vuejs.org/guide/quick-start.html","https://vuejs.org/api/reactivity-core.html"]),("svelte",SVELTE,svelte_files,"Svelte5.57.3;Vite8.3.5;vite-plugin-svelte7.3.1",["https://svelte.dev/docs/svelte/overview","https://svelte.dev/docs/svelte/$state"]),("angular",ANGULAR,angular_files,"Angular22.2.3;CLI/build22.2.5;TypeScript6.0.3",["https://angular.dev/installation","https://angular.dev/reference/versions","https://angular.dev/guide/signals"])]:
        book=Book(stack,version,sources,"Node24.15.0+ e npm; dipendenze del manifest. Angular22 richiede TypeScript>=6.0 e<6.1, non il latest7. L'esempio client funziona su loopback; nessuna pubblicazione automatica.")
        lifecycle(book,stack,wrapper)
        for row in rows:
            key,title,description,code,template,expected,*rest=row
            extra=rest[0] if rest else None
            if stack=="angular":files=wrapper(code,template,extra,rest[1] if len(rest)>1 else "",rest[2] if len(rest)>2 else "")
            else:files=wrapper(code,template,extra)
            book.add(key,title,description,files,commands="npm install\nnpm run dev",explanation=f"## Obiettivo\n{description}\n\n## File e avvio\nEsporta i file conservando src e le eventuali risorse public. Installa le dipendenze dalla cartella package.json e avvia il server sul loopback. La parte specifica è nel componente {'src/app.ts' if stack=='angular' else 'src/App.'+('vue' if stack=='vue' else 'svelte')}; i file aggiuntivi espongono il contratto del figlio o i dati richiesti.\n\n## Risultato da controllare\n{expected}\n\n## Integrazione\n{description} Il dataset dimostrativo è locale; la ricetta non richiede credenziali o un backend esterno.",expected=expected,tags=[stack,key,"component","reactivity"],errors=["Import non risolto: installare dal manifest esportato e mantenere i file di supporto.","Versione Node non supportata: controllare i requisiti del framework prima di reinstallare dipendenze."])
        capstone(book,stack)
        assert len(book.recipes)==(35 if stack=='vue' else 30)
        save_book(book)

if __name__=='__main__':build_all()
